def descends(a, b):
    # True if version with clock a supersedes (or equals) clock b
    return all(a.get(node, 0) >= n for node, n in b.items())

def compare(a, b):
    if descends(a, b) and descends(b, a): return "equal"
    if descends(a, b): return "a replaces b"
    if descends(b, a): return "b replaces a"
    return "concurrent: keep both"

D3 = {"Sx": 2, "Sy": 1}
D4 = {"Sx": 2, "Sz": 1}
D5 = {"Sx": 3, "Sy": 1, "Sz": 1}
print(compare(D3, D4))  # concurrent: keep both
print(compare(D5, D3))  # a replaces b
